    29→impl<T: BeaconChainTypes> NetworkBeaconProcessor<T> {
    30→    /* Auxiliary functions */
    31→
    32→    /// Disconnects and ban's a peer, sending a Goodbye request with the associated reason.
    33→    pub fn goodbye_peer(&self, peer_id: PeerId, reason: GoodbyeReason) {
    34→        self.send_network_message(NetworkMessage::GoodbyePeer {
    35→            peer_id,
    36→            reason,
    37→            source: ReportSource::Processor,
    38→        });
    39→    }
    40→
    41→    pub fn send_response(
    42→        &self,
    43→        peer_id: PeerId,
    44→        inbound_request_id: InboundRequestId,
    45→        response: Response<T::EthSpec>,
    46→    ) {
    47→        self.send_network_message(NetworkMessage::SendResponse {
    48→            peer_id,
    49→            inbound_request_id,
    50→            response,
    51→        })
    52→    }
    53→
    54→    pub fn send_error_response(
    55→        &self,
    56→        peer_id: PeerId,
    57→        error: RpcErrorResponse,
    58→        reason: String,
    59→        inbound_request_id: InboundRequestId,
    60→    ) {
    61→        self.send_network_message(NetworkMessage::SendErrorResponse {
    62→            peer_id,
    63→            error,
    64→            reason,
    65→            inbound_request_id,
    66→        })
    67→    }
    68→
    69→    /* Processing functions */
    70→
    71→    /// Process a `Status` message to determine if a peer is relevant to us. If the peer is
    72→    /// irrelevant the reason is returned.
    73→    fn check_peer_relevance(
    74→        &self,
    75→        remote: &StatusMessage,
    76→    ) -> Result<Option<String>, Box<BeaconChainError>> {
    77→        let local = self.chain.status_message();
    78→        let start_slot = |epoch: Epoch| epoch.start_slot(T::EthSpec::slots_per_epoch());
    79→
    80→        let irrelevant_reason = if local.fork_digest() != remote.fork_digest() {
    81→            // The node is on a different network/fork
    82→            Some(format!(
    83→                "Incompatible forks Ours:{} Theirs:{}",
    84→                hex::encode(local.fork_digest()),
    85→                hex::encode(remote.fork_digest())
    86→            ))
    87→        } else if *remote.head_slot()
    88→            > self
    89→                .chain
    90→                .slot()
    91→                .unwrap_or_else(|_| self.chain.slot_clock.genesis_slot())
    92→                + FUTURE_SLOT_TOLERANCE
    93→        {
    94→            // The remote's head is on a slot that is significantly ahead of what we consider the
    95→            // current slot. This could be because they are using a different genesis time, or that
    96→            // their or our system's clock is incorrect.
    97→            Some("Different system clocks or genesis time".to_string())
    98→        } else if (remote.finalized_epoch() == local.finalized_epoch()
    99→            && remote.finalized_root() == local.finalized_root())
   100→            || remote.finalized_root().is_zero()
   101→            || local.finalized_root().is_zero()
   102→            || remote.finalized_epoch() > local.finalized_epoch()
   103→        {
   104→            // Fast path. Remote finalized checkpoint is either identical, or genesis, or we are at
   105→            // genesis, or they are ahead. In all cases, we should allow this peer to connect to us
   106→            // so we can sync from them.
   107→            None
   108→        } else {
   109→            // Remote finalized epoch is less than ours.
   110→            let remote_finalized_slot = start_slot(*remote.finalized_epoch());
   111→            if remote_finalized_slot < self.chain.store.get_oldest_block_slot() {
   112→                // Peer's finalized checkpoint is older than anything in our DB. We are unlikely
   113→                // to be able to help them sync.
   114→                Some("Old finality out of range".to_string())
   115→            } else if remote_finalized_slot < self.chain.store.get_split_slot() {
   116→                // Peer's finalized slot is in range for a quick block root check in our freezer DB.
   117→                // If that block root check fails, reject them as they're on a different finalized
   118→                // chain.
   119→                if self
   120→                    .chain
   121→                    .block_root_at_slot(remote_finalized_slot, WhenSlotSkipped::Prev)
   122→                    .map(|root_opt| root_opt != Some(*remote.finalized_root()))
   123→                    .map_err(Box::new)?
   124→                {
   125→                    Some("Different finalized chain".to_string())
   126→                } else {
   127→                    None
   128→                }
   129→            } else {
   130→                // Peer's finality is older than ours, but newer than our split point, making a
   131→                // block root check infeasible. This case shouldn't happen particularly often so
   132→                // we give the peer the benefit of the doubt and let them connect to us.
   133→                None
   134→            }
   135→        };
   136→
   137→        Ok(irrelevant_reason)
   138→    }
   139→
   140→    pub fn process_status(&self, peer_id: PeerId, status: StatusMessage) {
   141→        match self.check_peer_relevance(&status) {
   142→            Ok(Some(irrelevant_reason)) => {
   143→                debug!(%peer_id, reason = irrelevant_reason, "Handshake Failure");
   144→                self.goodbye_peer(peer_id, GoodbyeReason::IrrelevantNetwork);
   145→            }
   146→            Ok(None) => {
   147→                let info = SyncInfo {
   148→                    head_slot: *status.head_slot(),
   149→                    head_root: *status.head_root(),
   150→                    finalized_epoch: *status.finalized_epoch(),
   151→                    finalized_root: *status.finalized_root(),
   152→                    earliest_available_slot: status.earliest_available_slot().ok().cloned(),
   153→                };
   154→                self.send_sync_message(SyncMessage::AddPeer(peer_id, info));
   155→            }
   156→            Err(e) => error!(
   157→                %peer_id,
   158→                error = ?e,
   159→                "Could not process status message"
   160→            ),
   161→        }
   162→    }
   163→
   164→    /// Handle a `BlocksByRoot` request from the peer.
   165→    #[instrument(
   166→        name = SPAN_HANDLE_BLOCKS_BY_ROOT_REQUEST,
   167→        parent = None,
   168→        level = "debug",
   169→        skip_all,
   170→        fields(peer_id = %peer_id, client = tracing::field::Empty)
   171→    )]
   172→    pub async fn handle_blocks_by_root_request(
   173→        self: Arc<Self>,
   174→        peer_id: PeerId,
   175→        inbound_request_id: InboundRequestId,
   176→        request: BlocksByRootRequest,
   177→    ) {
   178→        let client = self.network_globals.client(&peer_id);
   179→        Span::current().record("client", field::display(client.kind));
   180→
   181→        self.terminate_response_stream(
   182→            peer_id,
   183→            inbound_request_id,
   184→            self.clone()
   185→                .handle_blocks_by_root_request_inner(peer_id, inbound_request_id, request)
   186→                .await,
   187→            Response::BlocksByRoot,
   188→        );
   189→    }
   190→
   191→    /// Handle a `BlocksByRoot` request from the peer.
   192→    async fn handle_blocks_by_root_request_inner(
   193→        self: Arc<Self>,
   194→        peer_id: PeerId,
   195→        inbound_request_id: InboundRequestId,
   196→        request: BlocksByRootRequest,
   197→    ) -> Result<(), (RpcErrorResponse, &'static str)> {
   198→        let log_results = |peer_id, requested_blocks, send_block_count| {
   199→            debug!(
   200→                %peer_id,
   201→                requested = requested_blocks,
   202→                returned = %send_block_count,
   203→                "BlocksByRoot outgoing response processed"
   204→            );
   205→        };
   206→
   207→        let requested_blocks = request.block_roots().len();
   208→        let mut block_stream = match self
   209→            .chain
   210→            .get_blocks_checking_caches(request.block_roots().to_vec())
   211→        {
   212→            Ok(block_stream) => block_stream,
   213→            Err(e) => {
   214→                error!( error = ?e, "Error getting block stream");
   215→                return Err((RpcErrorResponse::ServerError, "Error getting block stream"));
   216→            }
   217→        };
   218→        // Fetching blocks is async because it may have to hit the execution layer for payloads.
   219→        let mut send_block_count = 0;
   220→        while let Some((root, result)) = block_stream.next().await {
   221→            match result.as_ref() {
   222→                Ok(Some(block)) => {
   223→                    self.send_response(
   224→                        peer_id,
   225→                        inbound_request_id,
   226→                        Response::BlocksByRoot(Some(block.clone())),
   227→                    );
   228→                    send_block_count += 1;
   229→                }
   230→                Ok(None) => {
   231→                    debug!(
   232→                        %peer_id,
   233→                        request_root = ?root,
   234→                        "Peer requested unknown block"
   235→                    );
   236→                }
   237→                Err(BeaconChainError::BlockHashMissingFromExecutionLayer(_)) => {
   238→                    debug!(
   239→                        block_root = ?root,
   240→                        reason = "execution layer not synced",
   241→                        "Failed to fetch execution payload for blocks by root request"
   242→                    );
   243→                    log_results(peer_id, requested_blocks, send_block_count);
   244→                    return Err((
   245→                        RpcErrorResponse::ResourceUnavailable,
   246→                        "Execution layer not synced",
   247→                    ));
   248→                }
   249→                Err(e) => {
   250→                    debug!(
   251→                        ?peer_id,
   252→                        request_root = ?root,
   253→                        error = ?e,
   254→                        "Error fetching block for peer"
   255→                    );
   256→                }
   257→            }
   258→        }
   259→        log_results(peer_id, requested_blocks, send_block_count);
   260→
   261→        Ok(())
   262→    }
   263→
   264→    /// Handle a `BlobsByRoot` request from the peer.
   265→    #[instrument(
   266→        name = SPAN_HANDLE_BLOBS_BY_ROOT_REQUEST,
   267→        parent = None,
   268→        level = "debug",
   269→        skip_all,
   270→        fields(peer_id = %peer_id, client = tracing::field::Empty)
   271→    )]
   272→    pub fn handle_blobs_by_root_request(
   273→        self: Arc<Self>,
   274→        peer_id: PeerId,
   275→        inbound_request_id: InboundRequestId,
   276→        request: BlobsByRootRequest,
   277→    ) {
   278→        let client = self.network_globals.client(&peer_id);
   279→        Span::current().record("client", field::display(client.kind));
   280→
   281→        self.terminate_response_stream(
   282→            peer_id,
   283→            inbound_request_id,
   284→            self.handle_blobs_by_root_request_inner(peer_id, inbound_request_id, request),
   285→            Response::BlobsByRoot,
   286→        );
   287→    }
   288→
   289→    /// Handle a `BlobsByRoot` request from the peer.
   290→    fn handle_blobs_by_root_request_inner(
   291→        &self,
   292→        peer_id: PeerId,
   293→        inbound_request_id: InboundRequestId,
   294→        request: BlobsByRootRequest,
   295→    ) -> Result<(), (RpcErrorResponse, &'static str)> {
   296→        let Some(requested_root) = request.blob_ids.as_slice().first().map(|id| id.block_root)
   297→        else {
   298→            // No blob ids requested.
   299→            return Ok(());
   300→        };
   301→        let requested_indices = request
   302→            .blob_ids
   303→            .as_slice()
   304→            .iter()
   305→            .map(|id| id.index)
   306→            .collect::<Vec<_>>();
   307→        let mut send_blob_count = 0;
   308→
   309→        let mut blob_list_results = HashMap::new();
   310→        for id in request.blob_ids.as_slice() {
   311→            // First attempt to get the blobs from the RPC cache.
   312→            if let Ok(Some(blob)) = self.chain.data_availability_checker.get_blob(id) {
   313→                self.send_response(
   314→                    peer_id,
   315→                    inbound_request_id,
   316→                    Response::BlobsByRoot(Some(blob)),
   317→                );
   318→                send_blob_count += 1;
   319→            } else {
   320→                let BlobIdentifier {
   321→                    block_root: root,
   322→                    index,
   323→                } = id;
   324→
   325→                let blob_list_result = match blob_list_results.entry(root) {
   326→                    Entry::Vacant(entry) => {
   327→                        entry.insert(self.chain.get_blobs_checking_early_attester_cache(root))
   328→                    }
   329→                    Entry::Occupied(entry) => entry.into_mut(),
   330→                };
   331→
   332→                match blob_list_result.as_ref() {
   333→                    Ok(blobs_sidecar_list) => {
   334→                        'inner: for blob_sidecar in blobs_sidecar_list.iter() {
   335→                            if blob_sidecar.index == *index {
   336→                                self.send_response(
   337→                                    peer_id,
   338→                                    inbound_request_id,
   339→                                    Response::BlobsByRoot(Some(blob_sidecar.clone())),
   340→                                );
   341→                                send_blob_count += 1;
   342→                                break 'inner;
   343→                            }
   344→                        }
   345→                    }
   346→                    Err(e) => {
   347→                        debug!(
   348→                            ?peer_id,
   349→                            request_root = ?root,
   350→                            error = ?e,
   351→                            "Error fetching blob for peer"
   352→                        );
   353→                    }
   354→                }
   355→            }
   356→        }
   357→        debug!(
   358→            %peer_id,
   359→            %requested_root,
   360→            ?requested_indices,
   361→            returned = send_blob_count,
   362→            "BlobsByRoot outgoing response processed"
   363→        );
   364→
   365→        Ok(())
   366→    }
   367→
   368→    /// Handle a `DataColumnsByRoot` request from the peer.
   369→    #[instrument(
   370→        name = SPAN_HANDLE_DATA_COLUMNS_BY_ROOT_REQUEST,
   371→        parent = None,
   372→        level = "debug",
   373→        skip_all,
   374→        fields(
   375→            peer_id = %peer_id,
   376→            client = tracing::field::Empty,
   377→            non_custody_indices = tracing::field::Empty,
   378→        )
   379→    )]
   380→    pub fn handle_data_columns_by_root_request(
   381→        self: Arc<Self>,
   382→        peer_id: PeerId,
   383→        inbound_request_id: InboundRequestId,
   384→        request: DataColumnsByRootRequest<T::EthSpec>,
   385→    ) {
   386→        let requested_columns = request
   387→            .data_column_ids
   388→            .iter()
   389→            .flat_map(|id| id.columns.clone())
   390→            .unique()
   391→            .collect::<Vec<_>>();
   392→        self.record_data_column_request_in_span(
   393→            &peer_id,
   394→            &requested_columns,
   395→            None,
   396→            Span::current(),
   397→        );
   398→
   399→        self.terminate_response_stream(
   400→            peer_id,
   401→            inbound_request_id,
   402→            self.handle_data_columns_by_root_request_inner(peer_id, inbound_request_id, request),
   403→            Response::DataColumnsByRoot,
   404→        );
   405→    }
   406→
   407→    /// Handle a `DataColumnsByRoot` request from the peer.
   408→    fn handle_data_columns_by_root_request_inner(
   409→        &self,
   410→        peer_id: PeerId,
   411→        inbound_request_id: InboundRequestId,
   412→        request: DataColumnsByRootRequest<T::EthSpec>,
   413→    ) -> Result<(), (RpcErrorResponse, &'static str)> {
   414→        let mut send_data_column_count = 0;
   415→        // Only attempt lookups for columns the node has advertised and is responsible for maintaining custody of.
   416→        let available_columns = self.chain.custody_columns_for_epoch(None);
   417→
   418→        for data_column_ids_by_root in request.data_column_ids.as_slice() {
   419→            let indices_to_retrieve = data_column_ids_by_root
   420→                .columns
   421→                .iter()
   422→                .copied()
   423→                .filter(|c| available_columns.contains(c))
   424→                .collect::<Vec<_>>();
   425→            match self.chain.get_data_columns_checking_all_caches(
   426→                data_column_ids_by_root.block_root,
   427→                &indices_to_retrieve,
   428→            ) {
   429→                Ok(data_columns) => {
   430→                    send_data_column_count += data_columns.len();
   431→                    for data_column in data_columns {
   432→                        self.send_response(
   433→                            peer_id,
   434→                            inbound_request_id,
   435→                            Response::DataColumnsByRoot(Some(data_column)),
   436→                        );
   437→                    }
   438→                }
